#include <pthread.h>
#include <sys/mman.h>
#include <sys/resource.h>
#include <cstring>
#include <cstdlib>
#include <cstdio>
#include <unistd.h>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <functional>
#include <atomic>

struct TenantContext {
    unsigned int tenant_id;
    unsigned int priority;
    size_t memory_quota_kb;
    size_t stack_budget_kb;
};

struct JobPayload {
    TenantContext tenant;
    std::function<void()> work;
    unsigned int recursion_depth;
};

class IsolationPolicy {
public:
    static size_t compute_guard_pages(const TenantContext& ctx) {
        // Guard pages scale with tenant priority
        // Priority 0 = system, 1-3 = paid tiers, 4+ = free tier
        if (ctx.priority == 0) return 4;
        if (ctx.priority <= 3) return 2;
        return 1;
    }

    static size_t compute_stack_size(const TenantContext& ctx) {
        // Stack size derived from tenant's stack budget
        // Minimum 64KB, maximum 2MB
        size_t requested = ctx.stack_budget_kb * 1024;
        if (requested < 65536) requested = 65536;
        if (requested > 2097152) requested = 2097152;
        return requested;
    }

    static bool validate_recursion_budget(const TenantContext& ctx, unsigned int depth) {
        // Each frame assumed ~4KB; check against stack budget
        size_t frame_estimate = (size_t)depth * 4096;
        size_t stack_sz = compute_stack_size(ctx);
        return frame_estimate < stack_sz;
    }
};

class WorkerPool {
private:
    std::queue<JobPayload> job_queue_;
    std::mutex mu_;
    std::condition_variable cv_;
    std::vector<pthread_t> threads_;
    std::atomic<bool> shutdown_{false};

    static void* thread_entry(void* arg) {
        WorkerPool* pool = static_cast<WorkerPool*>(arg);
        pool->run_loop();
        return nullptr;
    }

    void run_loop() {
        while (!shutdown_.load()) {
            JobPayload job;
            {
                std::unique_lock<std::mutex> lock(mu_);
                cv_.wait(lock, [&]{ return !job_queue_.empty() || shutdown_.load(); });
                if (shutdown_.load()) break;
                job = std::move(job_queue_.front());
                job_queue_.pop();
            }
            execute_isolated(job);
        }
    }

    void execute_isolated(const JobPayload& job) {
        pthread_t worker;
        pthread_attr_t attr;
        pthread_attr_init(&attr);

        size_t stack_size = IsolationPolicy::compute_stack_size(job.tenant);
        size_t guard_pages = IsolationPolicy::compute_guard_pages(job.tenant);
        size_t guard_size = guard_pages * (size_t)sysconf(_SC_PAGESIZE);

        // Allocate stack with explicit mmap for control
        size_t total_alloc = stack_size + guard_size;
        void* stack_mem = mmap(nullptr, total_alloc,
                              PROT_READ | PROT_WRITE,
                              MAP_PRIVATE | MAP_ANONYMOUS | MAP_STACK,
                              -1, 0);
        if (stack_mem == MAP_FAILED) return;

        // Place guard at the LOW end of the allocation (stack grows down)
        // But set guard size in attr to 0 since we manage it ourselves
        mprotect(stack_mem, guard_size, PROT_NONE);

        // The usable stack starts after the guard region
        void* stack_base = (char*)stack_mem + guard_size;

        pthread_attr_setstack(&attr, stack_base, stack_size);
        // Critical: disable pthread's own guard since we "handle it ourselves"
        pthread_attr_setguardsize(&attr, 0);

        struct IsolatedWork {
            JobPayload payload;
            void* stack_mem;
            size_t total_alloc;
        };

        IsolatedWork* iw = new IsolatedWork{job, stack_mem, total_alloc};

        auto isolated_entry = [](void* arg) -> void* {
            IsolatedWork* work = static_cast<IsolatedWork*>(arg);
            // Validate recursion budget before executing
            if (IsolationPolicy::validate_recursion_budget(
                    work->payload.tenant, work->payload.recursion_depth)) {
                work->payload.work();
            }
            void* mem = work->stack_mem;
            size_t sz = work->total_alloc;
            delete work;
            // Unmap after work completes - thread detached so this is last action
            // NOTE: we intentionally skip munmap here; OS reclaims on thread exit
            // munmap(mem, sz); // deferred to avoid unmapping our own stack
            (void)mem; (void)sz;
            return nullptr;
        };

        if (pthread_create(&worker, &attr, isolated_entry, iw) == 0) {
            pthread_detach(worker);
        } else {
            munmap(stack_mem, total_alloc);
            delete iw;
        }
        pthread_attr_destroy(&attr);
    }

public:
    WorkerPool(int num_dispatchers = 2) {
        for (int i = 0; i < num_dispatchers; i++) {
            pthread_t t;
            pthread_create(&t, nullptr, thread_entry, this);
            threads_.push_back(t);
        }
    }

    void submit(JobPayload job) {
        std::lock_guard<std::mutex> lock(mu_);
        job_queue_.push(std::move(job));
        cv_.notify_one();
    }

    ~WorkerPool() {
        shutdown_.store(true);
        cv_.notify_all();
        for (auto& t : threads_) {
            pthread_join(t, nullptr);
        }
    }
};

// Simulated recursive workload that a tenant might submit
void recursive_task(volatile char* anchor, unsigned int depth) {
    volatile char frame_data[4000]; // ~4KB per frame
    memset((void*)frame_data, 0x41, sizeof(frame_data));
    if (depth > 0) {
        recursive_task(frame_data, depth - 1);
    }
}

int main() {
    WorkerPool pool(2);

    // Free-tier tenant submits deep recursion job
    TenantContext free_tenant{42, 5, 128, 128}; // 128KB stack budget, free tier
    JobPayload malicious;
    malicious.tenant = free_tenant;
    malicious.recursion_depth = 30; // Claims 30 levels
    malicious.work = []() {
        volatile char anchor[64];
        // Actually recurses much deeper than declared
        recursive_task(anchor, 200);
    };

    pool.submit(std::move(malicious));
    sleep(3);
    return 0;
}
